<style>
	.orbit-container {
		width: 100%;
		max-width: 600px;
		aspect-ratio: 1;
    width: 38vw;
    height: auto;
    max-height: 500px;
	}

	.orbit-svg {
		width: 100%;
		height: 100%;
	}

    .orbit-svg *,
	.outer-circle {
		fill: var(--key, #1a365d);
	}

	/* 公転アニメーション - グループ全体を回転 */
	.orbiting-group
   {
		transform-origin: 289.6px 289.6px; /* SVGの中心 */
		animation: orbit var(--duration) linear infinite;
		animation-direction: normal;
	}


	/* 自転（逆回転）- テキストを正位置に保つ */
	.counter-rotate {
		animation: counter-orbit var(--duration) linear infinite;
	}
    

	/* 各円の自転の中心点を設定 */
	.orbit-1 .counter-rotate .circle {
    animation: orbits var(--duration) linear infinite;
		transform-origin: 289.6px 177.67px; /* 上の円の中心 */
	}

  .orbit-1 .counter-rotate {
    transform-origin: 289.6px 177.67px; /* 上の円の中心 */
  }

	.orbit-2 .counter-rotate {
		transform-origin: 172.12px 401.5px; /* 左下の円の中心 */
	}

	.orbit-3 .counter-rotate {
		transform-origin: 407.09px 401.5px; /* 右下の円の中心 */
	}

  @keyframes orbits {
		from {
			transform: rotate(360deg);
		}
		to {
			transform: rotate(0deg);
		}
	}

	@keyframes orbit {
		from {
			transform: rotate(0deg);
		}
		to {
			transform: rotate(calc(var(--direction) * 360deg));
		}
	}

	@keyframes counter-orbit {
		from {
			transform: rotate(0deg);
		}
		to {
			transform: rotate(calc(var(--direction) * -360deg));
		}
	}

	/* ホバーで一時停止 */
	.orbit-container:hover .orbiting-group,
	.orbit-container:hover .counter-rotate {
		animation-play-state: paused;
	}


  @media screen and (max-width: 834px) {
    .orbit-container {
      width: 100%;
    }
  }
</style>